import re
PAIR = re.compile(r'(?P<key>\w+)(?: = | )(?P<value>[^;]+);')
FLAG = re.compile(r'^-?[a-z]\w*$')
VALUED = re.compile(r'^(?P<kind>cs|nl|cr|tab|bs|vt|ff)\d$')
NAMES = {'cs': 'csize', 'nl': 'nldly', 'cr': 'crdly', 'tab': 'tabdly', 'bs': 'bsdly', 'vt': 'vtdly', 'ff': 'ffdly'}

def parse(lines):
    settings, modes, sl, ml = {}, [], [], []
    for i, ln in enumerate(lines):
        s = ln.strip()
        if not s:
            continue
        pairs = PAIR.findall(s) if ';' in s else []
        if pairs:
            for k, v in pairs:
                settings[k] = v.strip()
            sl.append(i)
            continue
        toks = s.split()
        if all(FLAG.match(t) for t in toks):
            for t in toks:
                m = VALUED.match(t)
                if m:
                    modes.append({'mode': NAMES[m.group('kind')], 'value': t})
                elif t.startswith('-'):
                    modes.append({'mode': t[1:], 'value': 'off'})
                else:
                    modes.append({'mode': t, 'value': 'on'})
            ml.append(i)
    return [{'name': 'settings', 'kind': 'kv', 'lines': sl, 'records': [settings]},
            {'name': 'modes', 'kind': 'table', 'lines': ml, 'records': modes}]
